'use strict';
const KEY='haymani_money_v3';
const LISTS=['projects','transactions','dailyTop3','weeklyScorecard','skills','fitness','content','sales','notes','overheads','smsImports','smsFingerprints'];
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-ET',{maximumFractionDigits:2}).format(Number(n)||0)+' Birr';
const p2=n=>String(n).padStart(2,'0');
const today=()=>{const d=new Date();return d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate())};   // local date (not UTC)
const newId=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);

/* ===== Ethiopian calendar (records are stored as ISO Gregorian dates; shown and entered as E.C.) ===== */
const EC_MONTHS=['Meskerem','Tikimt','Hidar','Tahsas','Tir','Yekatit','Megabit','Miazia','Ginbot','Sene','Hamle','Nehase','Pagume'];
const WEEKDAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const GM=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function g2j(y,m,d){const a=Math.floor((14-m)/12),yy=y+4800-a,mm=m+12*a-3;return d+Math.floor((153*mm+2)/5)+365*yy+Math.floor(yy/4)-Math.floor(yy/100)+Math.floor(yy/400)-32045}
function j2g(j){const a=j+32044,b=Math.floor((4*a+3)/146097),c=a-Math.floor(146097*b/4),d=Math.floor((4*c+3)/1461),e=c-Math.floor(1461*d/4),m=Math.floor((5*e+2)/153);return [100*b+d-4800+Math.floor(m/10),m+3-12*Math.floor(m/10),e-Math.floor((153*m+2)/5)+1]}
const EC_BASE=1723856;
function e2j(y,m,d){return EC_BASE+365+365*(y-1)+Math.floor(y/4)+30*m+d-31}
function j2e(j){const t=j-EC_BASE,r=t%1461,n=r%365+365*Math.floor(r/1460);return [4*Math.floor(t/1461)+Math.floor(r/365)-Math.floor(r/1460),Math.floor(n/30)+1,n%30+1]}
function isoToJ(iso){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');if(!m)return null;const y=+m[1],mo=+m[2],d=+m[3];if(mo<1||mo>12||d<1||d>31)return null;const j=g2j(y,mo,d),b=j2g(j);return b[0]===y&&b[1]===mo&&b[2]===d?j:null}
function jToIso(j){const g=j2g(j);return String(g[0]).padStart(4,'0')+'-'+p2(g[1])+'-'+p2(g[2])}
function isoToEc(iso){const j=isoToJ(iso);return j==null?null:j2e(j)}
function ecToIso(y,m,d){return jToIso(e2j(y,m,d))}
function ecMonthLen(y,m){return m<13?30:(y%4===3?6:5)}
function fd(iso){const e=isoToEc(iso);return e?e[2]+' '+EC_MONTHS[e[1]-1]+' '+e[0]:(iso||'')}
function fdLong(iso){const j=isoToJ(iso);return j==null?(iso||''):WEEKDAYS[(j+1)%7]+', '+fd(iso)+' E.C.'}
function gfmt(iso){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');return m?(+m[3])+' '+GM[+m[2]-1]+' '+m[1]:''}
function fdStart(r){return r.start==='0000-01-01'?'All dates':fd(r.start)}
function fdEnd(r){return r.end==='9999-12-31'?'All dates':fd(r.end)}
function rangeLabel(r){return r.start==='0000-01-01'?'All recorded dates':fd(r.start)+' to '+fd(r.end)}
// Ethiopian date picker: three selects (day / month / year). The real value lives in a hidden input with the given id, as an ISO date.
function dateField(id,iso,blank){
  let e=isoToEc(iso);if(!e&&!blank)e=isoToEc(today());
  const cur=isoToEc(today())[0];let y0=cur-8,y1=cur+4;if(e){y0=Math.min(y0,e[0]);y1=Math.max(y1,e[0])}
  const len=e?ecMonthLen(e[0],e[1]):30,ph=t=>blank?`<option value="">${t}</option>`:'';
  let D=ph('Day'),M=ph('Month'),Y=ph('Year');
  for(let d=1;d<=len;d++)D+=`<option value="${d}"${e&&e[2]===d?' selected':''}>${d}</option>`;
  EC_MONTHS.forEach((n,i)=>M+=`<option value="${i+1}"${e&&e[1]===i+1?' selected':''}>${n}</option>`);
  for(let y=y0;y<=y1;y++)Y+=`<option value="${y}"${e&&e[0]===y?' selected':''}>${y}</option>`;
  const v=e?ecToIso(e[0],e[1],e[2]):'';
  return `<div class="ecdate" data-ec="${esc(id)}" data-blank="${blank?1:0}"><div class="ecrow"><select class="ec-d" aria-label="Day">${D}</select><select class="ec-m" aria-label="Month">${M}</select><select class="ec-y" aria-label="Year (E.C.)">${Y}</select></div><input type="hidden" id="${esc(id)}" value="${v}"><div class="small ecg">${v?'Gregorian: '+gfmt(v):''}</div></div>`;
}
function ecSync(w,changed){
  const sd=w.querySelector('.ec-d'),sm=w.querySelector('.ec-m'),sy=w.querySelector('.ec-y'),h=w.querySelector('input[type=hidden]'),g=w.querySelector('.ecg');
  const y=+sy.value,m=+sm.value;
  if(y&&m&&changed!=='d'){const len=ecMonthLen(y,m);let d=+sd.value||0;if(d>len)d=len;let o=w.dataset.blank==='1'?'<option value="">Day</option>':'';for(let i=1;i<=len;i++)o+=`<option value="${i}">${i}</option>`;sd.innerHTML=o;sd.value=d?String(d):(w.dataset.blank==='1'?'':'1')}
  const d=+sd.value,iso=(y&&m&&d)?ecToIso(y,m,d):'';
  h.value=iso;if(g)g.textContent=iso?'Gregorian: '+gfmt(iso):'';
}
function setDateField(id,iso){
  const w=document.querySelector('.ecdate[data-ec="'+id+'"]');if(!w)return;
  const sy=w.querySelector('.ec-y'),sm=w.querySelector('.ec-m'),sd=w.querySelector('.ec-d'),e=isoToEc(iso);
  if(e){if(![...sy.options].some(o=>+o.value===e[0]))sy.add(new Option(e[0],e[0]));sy.value=String(e[0]);sm.value=String(e[1]);ecSync(w,'my');sd.value=String(e[2]);ecSync(w,'d')}
  else{sy.value='';sm.value='';ecSync(w,'my');sd.value='';ecSync(w,'d')}
}
document.addEventListener('change',e=>{const w=e.target.closest&&e.target.closest('.ecdate');if(w)ecSync(w,e.target.classList.contains('ec-d')?'d':'my')});

/* ===== data ===== */
function readLS(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch(e){return null}}
function fixDb(x){
  x=(x&&typeof x==='object'&&!Array.isArray(x))?x:{};
  LISTS.forEach(k=>{if(!Array.isArray(x[k]))x[k]=[]});
  if(!x.settings||typeof x.settings!=='object')x.settings={};
  x.settings.openingBalance=Number(x.settings.openingBalance)||0;
  if(!isoToJ(x.settings.openingDate))x.settings.openingDate='2000-01-01';
  x.projects.forEach(p=>{
    if(typeof p.quote==='string'){p.quoteNo=p.quoteNo||p.quote;p.quote=+p.price||0}   // earlier Project Money tracker shape
    p.quote=+p.quote||0;
    if(p.expected===undefined)p.expected=+p.expectedCost||0;
    p.expected=+p.expected||0;p.advance=+p.advance||0;p.start=p.start||'';p.deadline=p.deadline||'';p.notes=p.notes||'';
    if(p.advance>0&&!p.advanceMigrated&&!x.transactions.some(t=>t.projectId===p.id&&t.isAdvance)){
      x.transactions.push({id:newId(),date:isoToJ(p.start)?p.start:today(),projectId:p.id,projectName:p.name,type:'income',category:'Customer Payment',amount:p.advance,description:'Advance received (from earlier tracker)',paidTo:p.customer||'',method:'Other',isAdvance:true});
      p.advanceMigrated=true;
    }
  });
  x.transactions.forEach(t=>{
    if(t.description==='Advance received (from earlier tracker)')t.isAdvance=true;
    t.id=String(t.id||t.uid||newId());t.amount=+t.amount||0;
    if(!t.projectName){let p=x.projects.find(p=>p.id===t.projectId);if(p)t.projectName=p.name}
    if(t.paidTo===undefined)t.paidTo=t.person||'';
  });
  x.overheads.forEach(o=>{o.id=String(o.id||newId());o.amount=+o.amount||0});x.smsImports.forEach(i=>{if(!i||!i.date)i.date=today()});
  return x;
}
let db=fixDb(readLS(KEY)||readLS('haymani_money_v2')||readLS('haymani_money_v1'));
let curLedger=null,editTxId=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){toast('Could not save - storage may be full. Export a backup now.')}}
// The project's Advance is kept as ONE linked income transaction, so cash totals, ledger and reports always agree.
function syncAdvance(p){
  const a=+p.advance||0;let t=db.transactions.find(x=>x.projectId===p.id&&x.isAdvance);
  if(a>0){
    p.advanceMigrated=true;
    if(t){t.amount=a;t.projectName=p.name;t.paidTo=t.paidTo||p.customer||''}
    else db.transactions.push({id:newId(),date:isoToJ(p.start)?p.start:today(),projectId:p.id,projectName:p.name,type:'income',category:'Customer Payment',amount:a,description:'Advance received',paidTo:p.customer||'',method:'Other',isAdvance:true});
  }else if(t)db.transactions=db.transactions.filter(x=>x!==t);
}
function toast(m){let t=$('#toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2400)}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sum(a,fn){return a.reduce((s,x)=>s+(Number(fn(x))||0),0)}
function allMovements(){return [...db.transactions.map(x=>({...x,source:'project',direction:x.type==='income'?'in':'out',label:x.projectName||x.projectId||'Unassigned'})),...db.overheads.map(x=>({...x,source:'overhead',direction:'out',label:'Haymani overhead'}))]}
function movementDate(x){return x.date||'2000-01-01'}
function balanceAt(date=today()){const start=db.settings.openingDate||'2000-01-01';return Number(db.settings.openingBalance||0)+sum(allMovements().filter(x=>movementDate(x)>=start&&movementDate(x)<=date),x=>x.direction==='in'?x.amount:-x.amount)}
function totalFigures(list){return {income:sum(list.filter(x=>x.direction==='in'),x=>x.amount),projectExpenses:sum(list.filter(x=>x.source==='project'&&x.direction==='out'),x=>x.amount),overheadExpenses:sum(list.filter(x=>x.source==='overhead'),x=>x.amount),out:sum(list.filter(x=>x.direction==='out'),x=>x.amount)}}
function rangeFor(mode){const end=today(),j=isoToJ(end),e=j2e(j);let start=end;
  if(mode==='week')start=jToIso(j-((j+1)%7+6)%7);          // Monday of this week
  else if(mode==='month')start=ecToIso(e[0],e[1],1);        // 1st of the current Ethiopian month
  else if(mode==='year')start=ecToIso(e[0],1,1);            // Meskerem 1 of the current Ethiopian year
  return {start,end}}
function go(s){render(s)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.screen));
function render(s='dashboard'){editTxId=null;let el=$('#screen');if(s==='dashboard')el.innerHTML=dashboard();else if(s==='projects')el.innerHTML=projects();else if(s==='add')el.innerHTML=add();else if(s==='overhead')el.innerHTML=overhead();else if(s==='reports')el.innerHTML=reports();else if(s==='sms')el.innerHTML=smsImporter();else if(s==='more')el.innerHTML=more();else if(s==='plan')el.innerHTML=plan();else if(s==='control')el.innerHTML=control();bind(s)}
function dashboard(){let m=allMovements(),f=totalFigures(m),net=balanceAt();return `<div class="content"><div class="hero"><div class="small">BUILD THE MAN · BUILD THE BUSINESS · BUILD THE LIFE</div><div class="big">Haymani Command Center</div><div class="small">Your projects, cash and annual goals in one place.</div><div class="small">Today: ${esc(fdLong(today()))}</div></div><div class="notice">Net cash is calculated from your opening balance plus recorded money received minus project expenses and non-project expenses.</div><div class="cards"><div class="card"><div class="label">Projects</div><div class="value">${db.projects.length}</div></div><div class="card"><div class="label">Money Received</div><div class="value income">${money(f.income)}</div></div><div class="card"><div class="label">Total Expenses</div><div class="value expense">${money(f.out)}</div></div><div class="card"><div class="label">Net Cash Balance</div><div class="value ${net<0?'expense':'income'}">${money(net)}</div></div></div><div class="panel"><h3>Cash balance setup</h3><p class="small">Enter your cash/bank balance at the start of a date. Transactions dated on or after that date are then added or subtracted. Do not double-count any money already included in that opening balance.</p><label>Opening cash + bank balance at start of date (Birr)</label><input id="openingBalance" type="number" step="0.01" value="${Number(db.settings.openingBalance)||0}"><label>Opening balance date (E.C.)</label>${dateField('openingDate',db.settings.openingDate)}<button class="btn" id="saveOpening">Save opening balance</button></div><div class="panel"><h3>Annual targets</h3><div class="statline"><span>Personal savings target</span><b>1,500,000 Birr</b></div><div class="statline"><span>Haymani annual net profit target</span><b>2,500,000 Birr</b></div><div class="statline"><span>Body goal</span><b>52 → 65 kg</b></div><button class="btn" data-go="plan">Open Master Plan</button></div><div class="panel"><h3>Quick actions</h3><button class="btn" data-go="add">＋ Add project expense or payment</button><button class="btn secondary" data-go="overhead">＋ Add non-project expense</button><button class="btn secondary" data-go="reports">Generate a report</button></div><div class="panel"><h3>Recent money movements</h3>${recent(6)}</div></div>`}
function recent(n){let a=allMovements().sort((x,y)=>movementDate(y).localeCompare(movementDate(x))).slice(0,n);return a.length?a.map(x=>`<div class="item"><b class="${x.direction==='in'?'income':'expense'}">${x.direction==='in'?'+':'−'} ${money(x.amount)}</b><div class="muted">${esc(x.source==='overhead'?'Haymani overhead':x.label)} · ${esc(x.category)} · ${esc(x.description||'')}</div><div class="muted">${esc(fd(x.date))}</div></div>`).join(''):'<div class="empty">No transactions yet.</div>'}
function projects(){return `<div class="content"><h2>Projects</h2><button class="btn" data-go="newproject">＋ New Project</button>${unassignedTx().length?`<div class="panel"><h3>Unassigned money (${unassignedTx().length})</h3><p class="small">Not linked to a project, e.g. payments imported from bank SMS.</p><button class="btn secondary" data-ledger="__none">Open unassigned</button></div>`:''}<div class="panel">${db.projects.length?db.projects.map(p=>{let tx=db.transactions.filter(x=>x.projectId===p.id),i=sum(tx.filter(x=>x.type==='income'),x=>x.amount),o=sum(tx.filter(x=>x.type==='expense'),x=>x.amount);return `<div class="item"><h3>${esc(p.name)}</h3><div class="muted">${esc(p.customer)} · ${esc(p.id)}</div>${p.start||p.deadline?`<div class="muted">${p.start?'Start '+esc(fd(p.start)):''}${p.start&&p.deadline?' · ':''}${p.deadline?'Due '+esc(fd(p.deadline)):''}</div>`:''}${p.notes?`<div class="small">${esc(p.notes)}</div>`:''}<div class="statline"><span>Quoted</span><b>${money(p.quote)}</b></div><div class="statline"><span>Received</span><b class="income">${money(i)}</b></div>${+p.advance>0?`<div class="statline"><span>&nbsp;&nbsp;of which advance</span><b>${money(p.advance)}</b></div>`:''}<div class="statline"><span>Spent</span><b class="expense">${money(o)}</b></div><div class="statline"><span>Est. profit before overhead</span><b>${money((p.quote||0)-o)}</b></div><div class="statline"><span>Customer balance</span><b>${money((p.quote||0)-i)}</b></div><button class="btn secondary" data-ledger="${esc(p.id)}">Open ledger</button><button class="btn secondary" data-edit="${esc(p.id)}">✎ Edit project</button><button class="btn danger" data-delete="${esc(p.id)}">Delete project</button></div>`}).join(''):'<div class="empty">Create a project before entering project expenses.</div>'}</div></div>`}
function add(){return `<div class="content"><h2>Project money movement</h2><div class="panel"><label>Transaction type</label><select id="type"><option value="expense">Project expense / money out</option><option value="income">Customer payment / money in</option></select><label>Project</label><select id="project"><option value="">Select project</option>${db.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.id)} — ${esc(p.name)}</option>`).join('')}</select><label>Date (E.C.)</label>${dateField('date',today())}<label>Amount (Birr)</label><input id="amount" type="number" min="0.01" step="0.01" placeholder="0"><label>Category</label><select id="category"></select><label>Description</label><textarea id="desc" rows="2" placeholder="What was this money for?"></textarea><label>Paid to / received from</label><input id="paid" placeholder="Name or company"><label>Payment method</label><select id="method"><option>Cash</option><option>Bank Transfer</option><option>Mobile Money</option><option>Card</option><option>Other</option></select><button class="btn" id="saveTx">Save transaction</button></div></div>`}
function overhead(){return `<div class="content"><h2>Haymani non-project expenses</h2><div class="notice">Use this for costs that support the business overall, not costs assigned to one customer project.</div><div class="panel"><h3>Record overhead expense</h3><label>Date (E.C.)</label>${dateField('ohDate',today())}<label>Amount (Birr)</label><input id="ohAmount" type="number" min="0.01" step="0.01" placeholder="0"><label>Category</label><select id="ohCategory">${['Rent','Electricity','Water','Internet & Phone','Salaries & Wages','Marketing & Advertising','Machine Maintenance','Tools & Supplies','Transport not assigned to project','Office Supplies','Loan / Lease Payment','Bank Fees','Cleaning','Food & Allowance','Professional Services','Other Overhead'].map(x=>`<option>${x}</option>`).join('')}</select><label>Description</label><textarea id="ohDesc" rows="2" placeholder="What was paid for?"></textarea><label>Paid to</label><input id="ohPaid" placeholder="Person / supplier"><label>Payment method</label><select id="ohMethod"><option>Cash</option><option>Bank Transfer</option><option>Mobile Money</option><option>Card</option><option>Other</option></select><button class="btn" id="saveOverhead">Save overhead expense</button></div><div class="panel"><h3>Recorded overheads</h3>${db.overheads.length?[...db.overheads].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="item"><b class="expense">− ${money(x.amount)}</b><div>${esc(x.category)} · ${esc(x.description)}</div><div class="muted">${esc(fd(x.date))} · ${esc(x.paidTo)} · ${esc(x.method)}</div><button class="btn danger" data-ohdelete="${esc(x.id)}">Delete expense</button></div>`).join(''):'<div class="empty">No non-project expenses recorded yet.</div>'}</div></div>`}
function ledger(id){if(id==='__none')return unassignedLedger();let p=db.projects.find(x=>x.id===id);if(!p)return '<div class="content">Project not found.</div>';let tx=db.transactions.filter(x=>x.projectId===id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),i=sum(tx.filter(x=>x.type==='income'),x=>x.amount),o=sum(tx.filter(x=>x.type==='expense'),x=>x.amount);return `<div class="content"><button class="btn secondary" data-go="projects">← Projects</button><button class="btn secondary" data-edit="${esc(p.id)}">✎ Edit project</button><h2>${esc(p.name)}</h2><div class="panel"><div class="statline"><span>Quoted price</span><b>${money(p.quote)}</b></div>${+p.advance>0?`<div class="statline"><span>Advance received</span><b>${money(p.advance)}</b></div>`:''}${p.start?`<div class="statline"><span>Start date</span><b>${esc(fd(p.start))}</b></div>`:''}${p.deadline?`<div class="statline"><span>Deadline</span><b>${esc(fd(p.deadline))}</b></div>`:''}${p.notes?`<div class="statline"><span>Notes</span><b style="text-align:right;font-weight:500">${esc(p.notes)}</b></div>`:''}<div class="statline"><span>Customer payments</span><b class="income">${money(i)}</b></div><div class="statline"><span>Expenses</span><b class="expense">${money(o)}</b></div><div class="statline"><span>Cash movement</span><b>${money(i-o)}</b></div><div class="statline"><span>Est. profit before overhead</span><b>${money((p.quote||0)-o)}</b></div><div class="statline"><span>Customer balance</span><b>${money((p.quote||0)-i)}</b></div></div><div class="panel"><h3>Transactions</h3>${tx.length?tx.map(x=>`<div class="item"><b class="${x.type}">${x.type==='income'?'+':'−'} ${money(x.amount)}</b><div>${esc(x.category)} — ${esc(x.description)}</div><div class="muted">${esc(fd(x.date))} · ${esc(x.paidTo)}</div><button class="btn secondary" data-txedit="${esc(x.id)}">✎ Edit transaction</button><button class="btn danger" data-txdelete="${esc(x.id)}">Delete transaction</button></div>`).join(''):'<div class="empty">No transactions.</div>'}</div></div>`}
function reports(){let r=rangeFor('month');return `<div class="content"><h2>Financial reports</h2><div class="panel"><h3>Choose report period</h3><label>Quick period</label><select id="period"><option value="week">This week (Monday–today)</option><option value="month" selected>This Ethiopian month</option><option value="year">This Ethiopian year (Meskerem 1 – today)</option><option value="custom">Custom date range</option><option value="all">All recorded dates</option></select><label>From (E.C.)</label>${dateField('reportStart',r.start)}<label>To (E.C.)</label>${dateField('reportEnd',r.end)}<label>Include records</label><select id="reportType"><option value="all">Project + overhead + income</option><option value="project">Project transactions only</option><option value="overhead">Non-project expenses only</option></select><button class="btn" id="generateReport">Generate report</button></div><div id="reportOutput"></div></div>`}
function buildReport(){let mode=$('#period').value,r=mode==='all'?{start:'0000-01-01',end:'9999-12-31'}:mode==='custom'?{start:$('#reportStart').value,end:$('#reportEnd').value}:rangeFor(mode);if(mode!=='custom'&&mode!=='all'){setDateField('reportStart',r.start);setDateField('reportEnd',r.end)}if(!r.start||!r.end||r.start>r.end){toast('Please check the report date range');return}let type=$('#reportType').value,records=allMovements().filter(x=>movementDate(x)>=r.start&&movementDate(x)<=r.end&&(type==='all'||type==='project'&&x.source==='project'||type==='overhead'&&x.source==='overhead')).sort((a,b)=>movementDate(a).localeCompare(movementDate(b)));let f=totalFigures(records),startBalance=balanceAtBefore(r.start),endBalance=balanceAt(r.end),net=f.income-f.out;let title=`Haymani Financial Report (${rangeLabel(r)})`;let rows=records.map(x=>`<tr><td>${esc(fd(x.date))}</td><td>${x.source==='overhead'?'Overhead':esc(x.projectName||x.projectId||'Unassigned')}</td><td>${esc(x.category)}</td><td>${esc(x.description||'')}</td><td>${x.direction==='in'?money(x.amount):''}</td><td>${x.direction==='out'?money(x.amount):''}</td><td>${esc(x.method||'')}</td><td>${esc(x.paidTo||'')}</td></tr>`).join('');let summary=`<div class="cards"><div class="card"><div class="label">Money received</div><div class="value income">${money(f.income)}</div></div><div class="card"><div class="label">Project expenses</div><div class="value expense">${money(f.projectExpenses)}</div></div><div class="card"><div class="label">Non-project expenses</div><div class="value expense">${money(f.overheadExpenses)}</div></div><div class="card"><div class="label">Net movement</div><div class="value ${net<0?'expense':'income'}">${money(net)}</div></div></div>`;$('#reportOutput').innerHTML=`<div class="panel" id="reportPrintable"><h3>${esc(title)}</h3><p class="small">Generated ${esc(fd(today()))} E.C. · Amounts in Ethiopian Birr</p>${summary}<div class="statline"><span>Net cash balance at period end*</span><b>${money(endBalance)}</b></div><p class="small">*Calculated using opening balance and all recorded movements from the opening balance date through the report end date. For a filtered report, the balance still reflects all recorded movements.</p><div class="tablewrap"><table><thead><tr><th>Date (E.C.)</th><th>Project / Type</th><th>Category</th><th>Description</th><th>Money in</th><th>Money out</th><th>Method</th><th>Paid to/from</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No records in this period.</td></tr>'}</tbody></table></div><p class="small">${records.length} record(s) · Start balance before period: ${money(startBalance)}</p></div><button class="btn" id="pdfReport">Print / Save report as PDF</button><button class="btn secondary" id="excelReport">Export report for Excel (CSV)</button>`;$('#pdfReport').onclick=()=>printReport(title,r,records,f,endBalance,startBalance);$('#excelReport').onclick=()=>exportReportCsv(title,r,records,f,endBalance,startBalance)}
function balanceAtBefore(date){let j=isoToJ(date);return j==null?balanceAt(date):balanceAt(jToIso(j-1))}
function printReport(title,r,records,f,endBalance,startBalance){let w=window.open('','_blank');if(!w){document.body.classList.add('print-report');window.addEventListener('afterprint',()=>document.body.classList.remove('print-report'),{once:true});window.print();return}let html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:12px Arial,sans-serif;color:#222;padding:22px}h1{color:#8b6900}h2{margin-bottom:4px}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.stat{border:1px solid #ddd;padding:10px;min-width:130px}.muted{color:#666;font-size:11px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #ccc;padding:6px;text-align:left;overflow-wrap:anywhere}th{background:#eee}.num{text-align:right}@media print{button{display:none}body{padding:0}tr{break-inside:avoid}}</style></head><body><h1>HAYMANI</h1><h2>${esc(title)}</h2><div class="muted">Generated ${esc(fd(today()))} E.C. · Period ${esc(rangeLabel(r))} · Ethiopian Birr</div><div class="stats"><div class="stat">Money received<br><b>${money(f.income)}</b></div><div class="stat">Project expenses<br><b>${money(f.projectExpenses)}</b></div><div class="stat">Non-project expenses<br><b>${money(f.overheadExpenses)}</b></div><div class="stat">Net movement<br><b>${money(f.income-f.out)}</b></div><div class="stat">Ending net cash<br><b>${money(endBalance)}</b></div></div><p class="muted">Opening cash balance before period: ${money(startBalance)}. Ending cash is calculated from opening balance and all recorded movements through the period end.</p><table><thead><tr><th>Date (E.C.)</th><th>Project / Type</th><th>Category</th><th>Description</th><th>Money in</th><th>Money out</th><th>Method</th><th>Paid to/from</th></tr></thead><tbody>${records.map(x=>`<tr><td>${esc(fd(x.date))}</td><td>${x.source==='overhead'?'Haymani overhead':esc(x.projectName||x.projectId||'Unassigned')}</td><td>${esc(x.category)}</td><td>${esc(x.description||'')}</td><td>${x.direction==='in'?money(x.amount):''}</td><td>${x.direction==='out'?money(x.amount):''}</td><td>${esc(x.method||'')}</td><td>${esc(x.paidTo||'')}</td></tr>`).join('')||'<tr><td colspan="8">No records in this period.</td></tr>'}</tbody></table><p class="muted">${records.length} record(s). For PDF: choose Print, then Save as PDF (or Share/Save PDF on iPhone).</p><button onclick="window.print()">Print / Save as PDF</button><script>setTimeout(()=>window.print(),500)<\/script></body></html>`;w.document.open();w.document.write(html);w.document.close()}
function exportReportCsv(title,r,records,f,endBalance,startBalance){let rows=[['HAYMANI FINANCIAL REPORT',title],['Period start (E.C.)',fdStart(r)],['Period end (E.C.)',fdEnd(r)],['Generated (E.C.)',fd(today())],['Money received',f.income],['Project expenses',f.projectExpenses],['Non-project expenses',f.overheadExpenses],['Net movement',f.income-f.out],['Ending net cash',endBalance],['Opening balance before period',startBalance],[],['Date (E.C.)','Date (Gregorian)','Record type','Project','Category','Description','Money in (Birr)','Money out (Birr)','Payment method','Paid to/from'],...records.map(x=>[fd(x.date),x.date,x.source==='overhead'?'Overhead':'Project',x.projectName||x.projectId||'',x.category,x.description||'',x.direction==='in'?x.amount:'',x.direction==='out'?x.amount:'',x.method||'',x.paidTo||''])];downloadBlob(rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'haymani-financial-report-'+(r.start==='0000-01-01'?'all-dates':r.start+'-to-'+r.end)+'.csv','text/csv;charset=utf-8;');toast('Excel-compatible CSV exported')}
function downloadBlob(content,name,type){let blob=new Blob(['\ufeff',content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function plan(){return `<div class="content"><h2>Master Plan · 2019 E.C.</h2><div class="hero"><div class="small">CORE THEME</div><div class="big">Build the Man. Build the Business. Build the Life.</div></div><div class="panel"><h3>Annual targets</h3><div class="statline"><span>Personal savings</span><b>1,500,000 Birr</b></div><div class="statline"><span>Starting savings</span><b>20,000 Birr</b></div><div class="statline"><span>Haymani net profit</span><b>2,500,000 Birr</b></div><div class="statline"><span>Body goal</span><b>52 kg → 65 kg</b></div><div class="statline"><span>Skill priority</span><b>Sales → Communication → Management</b></div></div><div class="panel"><h3>Daily operating system</h3><ul><li>Choose your daily Top 3: revenue, business execution, personal development.</li><li>Protect one hour for development: 30 min learning, 20 min practice, 10 min application/review.</li><li>Use a 5-minute start, phone away, creation before consumption, and no-zero-days.</li><li>Set an owner, deadline and next action for every important task.</li></ul><button class="btn" data-go="control">Open Control Center</button></div><div class="panel"><h3>Weekly scorecard targets</h3>${[['Prospects',50],['Meaningful conversations',20],['Quotations',10],['Serious follow-ups',5],['Relationship-building meetings',1],['Major content pieces',3],['Gym sessions',4],['Weekly reviews',1],['CEO/system improvements',1]].map(([k,v])=>`<div class="statline"><span>${k}</span><b>${v} / week</b></div>`).join('')}</div><div class="panel"><h3>12-month profit roadmap</h3>${[75000,100000,125000,150000,180000,220000,230000,250000,270000,280000,300000,320000].map((v,i)=>`<div class="statline"><span>Month ${i+1}</span><b>${money(v)}</b></div>`).join('')}</div><div class="panel"><a class="doclink" href="master-plan.docx" download>⇩ Download Master Plan (DOCX)</a></div></div>`}
function control(){return `<div class="content"><h2>Control Center</h2><div class="panel"><a class="doclink" href="control-workbook.xlsx" download>⇩ Download Control Workbook (XLSX)</a></div><div class="panel"><h3>Personal savings tracker</h3><label>Current savings (Birr)</label><input id="savingsActual" type="number" placeholder="Enter actual savings" value="${db.savings?.actual??''}"><label>Monthly new savings (Birr)</label><input id="savingsMonth" type="number" placeholder="Enter this month's savings" value="${db.savings?.month??''}"><button class="btn" id="saveSavings">Save savings snapshot</button><div id="savingsResult" class="small"></div></div><div class="panel"><h3>Weekly scorecard</h3><label>Prospects contacted</label><input id="prospects" type="number" value="0"><label>Meaningful conversations</label><input id="conversations" type="number" value="0"><label>Quotations sent</label><input id="quotes" type="number" value="0"><label>Serious follow-ups</label><input id="followups" type="number" value="0"><label>Major content pieces published</label><input id="posts" type="number" value="0"><button class="btn" id="saveScore">Save weekly scorecard</button><div id="scoreResult" class="small"></div></div><div class="panel"><h3>Daily Top 3</h3><label>Revenue task</label><input id="taskRevenue" placeholder="Today's revenue-producing action"><label>Business task</label><input id="taskBusiness" placeholder="Business execution task"><label>Personal development task</label><input id="taskPersonal" placeholder="Learning / health / personal task"><button class="btn" id="saveTop3">Save today's Top 3</button><div id="top3Result" class="small"></div></div></div>`}
function more(){return `<div class="content"><h2>More tools</h2><button class="btn" data-go="plan">Master Plan & annual targets</button><button class="btn secondary" data-go="control">Control Center & workbook</button><div class="panel"><h3>Backup and restore</h3><p class="small">Backups contain your projects, transactions, overheads, and settings. Save them regularly, especially before updating the app.</p><button class="btn" id="backupNow">Download full JSON backup</button><label>Restore from a JSON backup</label><input type="file" id="restoreFile" accept="application/json,.json"><button class="btn secondary" id="restoreNow">Restore selected backup</button></div><div class="panel"><h3>Data safety</h3><p class="small">Your records are stored in this browser on this device. They do not automatically sync to another phone or computer. Export backups regularly.</p></div></div>`}
function bind(s){document.querySelectorAll('[data-sms-approve]').forEach(b=>b.onclick=()=>saveSmsReview(b.dataset.smsApprove));document.querySelectorAll('[data-sms-discard]').forEach(b=>b.onclick=()=>{if(confirm('Discard this imported message?')){db.smsFingerprints.push(db.smsImports.find(x=>x.id===b.dataset.smsDiscard)?.fingerprint||'');db.smsImports=db.smsImports.filter(x=>x.id!==b.dataset.smsDiscard);save();render('sms')}});document.querySelectorAll('[data-sms-pending]').forEach(b=>b.onclick=()=>toast('Kept in review queue'));if(s==='sms'&&$('#parseSms'))$('#parseSms').onclick=()=>{let raw=$('#smsText').value;if($('#smsFile').files[0]){let reader=new FileReader();reader.onload=()=>processSmsText(reader.result);reader.readAsText($('#smsFile').files[0])}else processSmsText(raw)};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{let x=b.dataset.go;if(x==='newproject')renderNew();else if(x==='daily')renderDaily();else render(x)});document.querySelectorAll('[data-ledger]').forEach(b=>b.onclick=()=>{let id=b.dataset.ledger;curLedger=id;$('#screen').innerHTML=ledger(id);bind('ledger')});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>renderNew(b.dataset.edit,s));document.querySelectorAll('[data-txedit]').forEach(b=>b.onclick=()=>renderTxEdit(b.dataset.txedit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this project and its transactions?')){db.transactions.filter(x=>x.projectId===b.dataset.delete&&x.smsFingerprint).forEach(x=>{db.smsFingerprints=db.smsFingerprints.filter(f=>f!==x.smsFingerprint)});db.projects=db.projects.filter(p=>p.id!==b.dataset.delete);db.transactions=db.transactions.filter(x=>x.projectId!==b.dataset.delete);save();render('projects')}});document.querySelectorAll('[data-txdelete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this transaction?')){let dt=db.transactions.find(x=>x.id===b.dataset.txdelete);if(dt&&dt.smsFingerprint)db.smsFingerprints=db.smsFingerprints.filter(f=>f!==dt.smsFingerprint);if(dt&&dt.isAdvance){let dp=db.projects.find(p=>p.id===dt.projectId);if(dp)dp.advance=0}db.transactions=db.transactions.filter(x=>x.id!==b.dataset.txdelete);save();$('#screen').innerHTML=ledger(curLedger||(dt&&dt.projectId));bind('ledger')}});document.querySelectorAll('[data-ohdelete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this overhead expense?')){let od=db.overheads.find(x=>x.id===b.dataset.ohdelete);if(od&&od.smsFingerprint)db.smsFingerprints=db.smsFingerprints.filter(f=>f!==od.smsFingerprint);db.overheads=db.overheads.filter(x=>x.id!==b.dataset.ohdelete);save();render('overhead')}});
if(s==='dashboard'&&$('#saveOpening'))$('#saveOpening').onclick=()=>{let n=Number($('#openingBalance').value);if(!Number.isFinite(n)){toast('Enter a valid opening balance');return}db.settings.openingBalance=n;db.settings.openingDate=$('#openingDate').value||'2000-01-01';save();toast('Opening balance saved');render('dashboard')};if(s==='add'&&$('#saveTx')){$('#saveTx').onclick=saveTx;$('#type').onchange=fillCats;fillCats()}
if(s==='overhead'&&$('#saveOverhead'))$('#saveOverhead').onclick=()=>{let amount=Number($('#ohAmount').value);if(!(amount>0)){toast('Enter an amount greater than zero');return}db.overheads.push({id:newId(),date:$('#ohDate').value||today(),amount,category:$('#ohCategory').value,description:$('#ohDesc').value.trim(),paidTo:$('#ohPaid').value.trim(),method:$('#ohMethod').value});save();toast('Overhead expense saved');render('overhead')};
if(s==='reports'){if($('#generateReport'))$('#generateReport').onclick=buildReport;$('#period').onchange=()=>{let mode=$('#period').value;if(mode==='custom')return;let r=mode==='all'?{start:'2000-01-01',end:today()}:rangeFor(mode);setDateField('reportStart',r.start);setDateField('reportEnd',r.end)}};
if(s==='control'){showLast();let a=$('#saveSavings');if(a)a.onclick=()=>{db.savings={actual:Number($('#savingsActual').value)||0,month:Number($('#savingsMonth').value)||0,date:today()};save();$('#savingsResult').textContent=`Saved. Current savings: ${money(db.savings.actual)}. Gap to target: ${money(1500000-db.savings.actual)}.`};let w=$('#saveScore');if(w)w.onclick=()=>{let o={date:today(),prospects:+$('#prospects').value||0,conversations:+$('#conversations').value||0,quotes:+$('#quotes').value||0,followups:+$('#followups').value||0,posts:+$('#posts').value||0};db.weeklyScorecard.push(o);save();$('#scoreResult').textContent=`Saved. Prospects ${o.prospects}/50 · conversations ${o.conversations}/20 · quotes ${o.quotes}/10 · follow-ups ${o.followups}/5 · posts ${o.posts}/3.`};let t=$('#saveTop3');if(t)t.onclick=()=>{db.dailyTop3.push({date:today(),revenue:$('#taskRevenue').value,business:$('#taskBusiness').value,personal:$('#taskPersonal').value});save();$('#top3Result').textContent='Top 3 saved for today.'}}
if(s==='more'){let b=$('#backupNow');if(b)b.onclick=downloadBackup;let rr=$('#restoreNow');if(rr)rr.onclick=restoreBackup}}
function showLast(){let s=db.savings,w=db.weeklyScorecard[db.weeklyScorecard.length-1],t=db.dailyTop3[db.dailyTop3.length-1];
  if(s)$('#savingsResult').textContent=`Last snapshot (${fd(s.date)}): ${money(s.actual)} saved. Gap to target: ${money(1500000-s.actual)}.`;
  if(w)$('#scoreResult').textContent=`Last scorecard (${fd(w.date)}): prospects ${w.prospects}/50 · conversations ${w.conversations}/20 · quotes ${w.quotes}/10 · follow-ups ${w.followups}/5 · posts ${w.posts}/3.`;
  if(t)$('#top3Result').textContent=`Last Top 3 (${fd(t.date)}): ${[t.revenue,t.business,t.personal].filter(Boolean).join(' · ')}`}
function smsImporter(){return `<div class="content"><h2>Bank SMS Importer</h2><div class="notice">Paste exported bank SMS messages or upload a .txt file. The app suggests a transaction type and category; nothing is recorded until you approve it.</div><div class="panel"><h3>Import messages</h3><label>Paste one or more CBE / Telebirr messages</label><textarea id="smsText" rows="8" placeholder="Paste WhatsApp-exported bank SMS text here..."></textarea><label>Or choose a TXT file</label><input id="smsFile" type="file" accept=".txt,text/plain"><button class="btn" id="parseSms">Analyze messages</button><p class="small">This app cannot read your SMS inbox directly. Import is manual and stays on this device.</p></div><div class="panel"><h3>Review queue (${db.smsImports.length})</h3>${db.smsImports.length?db.smsImports.map(smsReviewCard).join(''):'<div class="empty">No messages waiting for review.</div>'}</div><div class="panel"><h3>Import safety</h3><p class="small">Duplicate references and matching message fingerprints are blocked. Balance snapshots are never treated as income. Transfers are not counted as expenses unless you explicitly classify them as a real business expense. Bank fees are shown separately.</p></div></div>`}
function smsReviewCard(x){let projects=db.projects.map(p=>`<option value="${esc(p.id)}" ${x.projectId===p.id?'selected':''}>${esc(p.id)} — ${esc(p.name)}</option>`).join('');return `<div class="item"><div class="statline"><b>${esc(x.bank)} · ${esc(x.direction==='in'?'Money received':'Money sent')}</b><span class="pill">${esc(x.confidence||'Review')}</span></div><div class="value ${x.direction==='in'?'income':'expense'}">${x.direction==='in'?'+':'−'} ${money(x.amount)}</div><div class="muted">${esc(x.counterparty||'Unknown sender/recipient')} · Ref: ${esc(x.reference||'Not found')}${x.date.length>10?' · Message time '+esc(x.date.slice(11,16)):''}</div><label>Transaction date (E.C.)</label>${dateField('sms-date-'+x.id,x.date.slice(0,10))}${x.fee?`<div class="muted">Fees: ${money(x.fee)} · Total debit: ${money(x.amount+x.fee)}</div>`:''}<div class="small">${esc(x.suggestion||'No confident category suggestion. Please review.')}</div><label>How should this be recorded?</label><select id="sms-kind-${esc(x.id)}"><option value="${x.direction==='in'?'income':'unknown'}" ${x.suggestedKind==='income'||x.suggestedKind==='unknown'?'selected':''}>${x.direction==='in'?'Customer / business income':'Choose classification…'}</option><option value="project" ${x.suggestedKind==='project'?'selected':''}>Project expense</option><option value="overhead" ${x.suggestedKind==='overhead'?'selected':''}>Haymani overhead</option><option value="transfer" ${x.suggestedKind==='transfer'?'selected':''}>Transfer between my own accounts (not income/expense)</option><option value="personal" ${x.suggestedKind==='personal'?'selected':''}>Personal / not Haymani</option><option value="unknown" ${x.suggestedKind==='unknown'?'selected':''}>Still uncertain — keep pending</option></select><div id="sms-project-wrap-${esc(x.id)}"><label>${x.direction==='out'?'Project (required for a project expense)':'Project (optional - links this payment to a project)'}</label><select id="sms-project-${esc(x.id)}"><option value="">Select project</option>${projects}</select></div><div id="sms-cat-wrap-${esc(x.id)}"><label>Category / note</label><input id="sms-cat-${esc(x.id)}" value="${esc(x.category||'Other')}" placeholder="Category"></div><label>Extra note</label><input id="sms-note-${esc(x.id)}" value="${esc(x.note||'')}" placeholder="Purpose, invoice, or clarification"><button class="btn" data-sms-approve="${esc(x.id)}">Approve and save</button><button class="btn secondary" data-sms-pending="${esc(x.id)}">Keep pending</button><button class="btn danger" data-sms-discard="${esc(x.id)}">Discard message</button><details><summary class="small">Original message</summary><p class="small">${esc(x.raw)}</p></details></div>`}
function smsDate(s,fallback){let m=s.match(/\bon\s+(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}:\d{2}:\d{2})/i);if(m)return `${m[3]}-${m[2]}-${m[1]}T${m[4]}`;return fallback||today()}
function suggestFromHistory(name,isIn){if(!name)return null;let key=name.toLowerCase().replace(/[^a-z0-9]/g,'');let matches=[...db.transactions.map(x=>({...x,_kind:x.type==='income'?'income':'project',_label:x.projectName||x.projectId||x.category})),...db.overheads.map(x=>({...x,_kind:'overhead',_label:x.category}))].filter(x=>String(x.paidTo||'').toLowerCase().replace(/[^a-z0-9]/g,'')===key);let match=matches[matches.length-1];if(!match)return null;if(isIn&&match._kind!=='income')return null;if(!isIn&&match._kind==='income')return null;return {kind:match._kind,label:match._label,category:match.category||'Other',projectId:match.projectId||''}}
function parseSmsText(raw){let blocks=raw.split(/(?=\[\d{1,2}\/\d{1,2}\/\d{4}\s+\d{1,2}:\d{2}\s*(?:AM|PM)\])/i).map(s=>s.trim()).filter(Boolean);if(blocks.length===1)blocks=raw.split(/(?=Dear\s+(?:Samuel|Customer))/i).map(s=>s.trim()).filter(Boolean);let out=[];for(let b of blocks){let bank=/CBE|Commercial Bank of Ethiopia/i.test(b)?'CBE':/Telebirr/i.test(b)?'Telebirr':null;if(!bank)continue;let isIn=/you have received|you have received ETB/i.test(b),isOut=/you have transferred|successfully transferred/i.test(b);if(!isIn&&!isOut)continue;let amtMatch=b.match(/(?:received|transferred)\s+ETB\s*([\d,]+\.\d{2})/i)||b.match(/transferred ETB\s*([\d,]+\.\d{2})/i);if(!amtMatch)continue;let amount=Number(amtMatch[1].replace(/,/g,''));let fee=0;let feeMatches=[...b.matchAll(/(?:service fee(?: of| is)?|service charge of|VAT\(15%\) of|15% VAT on the service fee is|Disaster Recovery\(5%\) of)\s*(?:ETB)?\s*([\d,]+\.\d{2})/gi)];fee=feeMatches.reduce((a,m)=>a+Number(m[1].replace(/,/g,'')),0);let counterparty='';if(bank==='CBE'){let m=b.match(/from account [^()]+\(([^)]+)\)/i)||b.match(/to account [^()]+\(([^)]+)\)/i);if(m)counterparty=m[1]}else{let m=b.match(/(?:to|from)\s+(.+?)\s+\(\d+\*+\d+\)/i);if(m)counterparty=m[1].trim()}let ref=(b.match(/transaction number is\s+([A-Z0-9]+)/i)||[])[1]||'';let fallback=(b.match(/\[(\d{1,2}\/\d{1,2}\/\d{4}\s+\d{1,2}:\d{2}\s*(?:AM|PM))\]/i)||[])[1];let date=smsDate(b,fallback?parseWhatsAppDate(fallback):today());let fingerprint=[bank,isIn?'in':'out',date.slice(0,10),amount.toFixed(2),counterparty.toLowerCase(),ref].join('|');let suggestedKind=isIn?'income':'unknown',suggestion=isIn?'Incoming payment detected. Confirm whether it belongs to a Haymani project, overhead refund, or personal account.':'Outgoing transfer detected. Confirm project, overhead, own-account transfer, or personal use.';if(isOut&&/Wolderagawi Tolosa And Or Samuel/i.test(counterparty)){suggestedKind='transfer';suggestion='Possible transfer between own/joint accounts. Do not count it as an expense unless confirmed.'}let history=suggestFromHistory(counterparty,isIn);if(history){suggestedKind=history.kind;suggestion=`Suggested from your previous records: ${history.label}. Please confirm.`}let item={id:'sms-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),bank,direction:isIn?'in':'out',amount,fee,counterparty,reference:ref,date,raw:b,fingerprint,suggestedKind,suggestion,confidence:history?'History match':(ref?'Parsed':'Review'),category:history?.category||(isIn?'Customer Payment':'Other'),projectId:history?.projectId||''};if(!db.smsFingerprints.includes(fingerprint)&&!db.smsImports.some(x=>x.fingerprint===fingerprint)&&!out.some(x=>x.fingerprint===fingerprint))out.push(item)}return out}
function processSmsText(raw){if(!raw.trim()){toast('Paste messages or choose a TXT file');return}let found=parseSmsText(raw);if(!found.length){toast('No new supported CBE / Telebirr transactions found');return}db.smsImports.push(...found);save();toast(`${found.length} message(s) added for review`);render('sms')}
function parseWhatsAppDate(s){let m=s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}:\d{2})\s*(AM|PM)/i);if(!m)return today();let mm=+m[1],dd=+m[2],yy=m[3],h=+m[4].split(':')[0];if(m[5].toUpperCase()==='PM'&&h<12)h+=12;if(m[5].toUpperCase()==='AM'&&h===12)h=0;return `${yy}-${String(mm).padStart(2,'0')}-${String(dd).padStart(2,'0')}T${String(h).padStart(2,'0')}:${m[4].split(':')[1]}`}
function saveSmsReview(id){let x=db.smsImports.find(v=>v.id===id);if(!x)return;let kind=$(`#sms-kind-${id}`).value;if(kind==='unknown'){toast('Still uncertain — left in review queue');return}let category=$(`#sms-cat-${id}`)?.value.trim()||'Other',note=$(`#sms-note-${id}`)?.value.trim()||'',method=x.bank==='CBE'?'Bank Transfer':'Mobile Money',d=$('#sms-date-'+id)?.value||x.date.slice(0,10);if(kind==='income'){let ip=db.projects.find(p=>p.id===($('#sms-project-'+id)?.value||''));db.transactions.push({id:newId(),date:d,projectId:ip?ip.id:'',projectName:ip?ip.name:'',type:'income',category:'Customer Payment',amount:x.amount,description:`Bank SMS: ${note||x.counterparty}`,paidTo:x.counterparty,method,smsReference:x.reference,smsFingerprint:x.fingerprint})}else if(kind==='project'){let pid=$(`#sms-project-${id}`).value;if(!pid){toast('Choose a project before saving');return}let p=db.projects.find(p=>p.id===pid);db.transactions.push({id:newId(),date:d,projectId:pid,projectName:p.name,type:'expense',category,amount:x.amount,description:`Bank SMS: ${note}`,paidTo:x.counterparty,method,smsReference:x.reference,smsFingerprint:x.fingerprint})}else if(kind==='overhead'){db.overheads.push({id:newId(),date:d,amount:x.amount,category,description:`Bank SMS: ${note}`,paidTo:x.counterparty,method,smsReference:x.reference,smsFingerprint:x.fingerprint})}else if(kind==='transfer'||kind==='personal'){db.smsFingerprints.push(x.fingerprint);db.smsImports=db.smsImports.filter(v=>v.id!==id);save();toast(kind==='transfer'?'Transfer marked; not counted as income or expense':'Personal transaction excluded from Haymani books');render('sms');return}if(x.fee>0&&!db.overheads.some(o=>o.smsFeeFor===x.fingerprint)){db.overheads.push({smsFeeFor:x.fingerprint,id:newId(),date:d,amount:x.fee,category:'Bank Fees',description:`${x.bank} SMS fee${x.reference?' · '+x.reference:''}`,paidTo:x.bank,method})}db.smsFingerprints.push(x.fingerprint);db.smsImports=db.smsImports.filter(v=>v.id!==id);save();toast('Approved transaction saved');render('sms')}
function unassignedTx(){return db.transactions.filter(x=>!x.projectId||!db.projects.some(p=>p.id===x.projectId))}
function unassignedLedger(){const tx=unassignedTx().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  return `<div class="content"><button class="btn secondary" data-go="projects">← Projects</button><h2>Unassigned money</h2><div class="notice">Payments (for example imported from bank SMS) that are not linked to a project. They already count in cash and reports. Edit one to link it to a project.</div><div class="panel">${tx.length?tx.map(x=>`<div class="item"><b class="${x.type}">${x.type==='income'?'+':'−'} ${money(x.amount)}</b><div>${esc(x.category)} — ${esc(x.description)}</div><div class="muted">${esc(fd(x.date))} · ${esc(x.paidTo)}</div><button class="btn secondary" data-txedit="${esc(x.id)}">✎ Edit transaction (assign project)</button><button class="btn danger" data-txdelete="${esc(x.id)}">Delete transaction</button></div>`).join(''):'<div class="empty">Nothing unassigned.</div>'}</div></div>`}
function newProjectForm(p){p=p||{};const e=!!p.id,v=k=>esc(p[k]==null?'':p[k]),n=k=>+p[k]?esc(p[k]):'';
  return `<div class="content"><h2>${e?'Edit project':'New project'}</h2><div class="panel"><label>Project ID</label><input id="pid" placeholder="HAY-001" value="${v('id')}" ${e?'readonly':''}>${e?'<div class="small">Project ID cannot be changed because transactions are linked to it.</div>':''}<label>Customer</label><input id="customer" value="${v('customer')}"><label>Project name</label><input id="pname" value="${v('name')}"><label>Quotation number</label><input id="quoteNo" value="${v('quoteNo')}"><label>Quoted price (Birr)</label><input id="quote" type="number" inputmode="decimal" value="${n('quote')}"><label>Expected cost (Birr)</label><input id="expected" type="number" inputmode="decimal" value="${n('expected')}"><label>Advance received (Birr)</label><input id="advance" type="number" inputmode="decimal" value="${n('advance')}"><div class="small">Recorded automatically as a customer payment in the project ledger.</div><label>Start date (E.C.)</label>${dateField('start',p.start,true)}<label>Deadline (E.C.)</label>${dateField('deadline',p.deadline,true)}<label>Notes</label><textarea id="notes" rows="3" placeholder="Anything to remember about this project">${v('notes')}</textarea><button class="btn" id="saveProject">${e?'Save changes':'Create project'}</button><button class="btn secondary" id="cancelProject">Cancel</button></div></div>`}
function renderNew(eid,from){
  let ex=eid?db.projects.find(p=>p.id===eid):null;
  const back=()=>{if(ex&&from==='ledger'){curLedger=ex.id;$('#screen').innerHTML=ledger(ex.id);bind('ledger')}else render('projects')};
  $('#screen').innerHTML=newProjectForm(ex||{start:today()});
  $('#cancelProject').onclick=back;
  $('#saveProject').onclick=()=>{
    let id=ex?ex.id:$('#pid').value.trim(),name=$('#pname').value.trim();
    if(!id||!name){toast('Project ID and name are required');return}
    if(!ex&&db.projects.some(p=>p.id===id)){toast('Project ID already exists');return}
    let o={id,customer:$('#customer').value.trim(),name,quoteNo:$('#quoteNo').value.trim(),quote:+$('#quote').value||0,expected:+$('#expected').value||0,advance:Math.max(0,+$('#advance').value||0),start:$('#start').value,deadline:$('#deadline').value,notes:$('#notes').value.trim()};
    let p;if(ex){Object.assign(ex,o);p=ex;db.transactions.forEach(t=>{if(t.projectId===id)t.projectName=name})}else{db.projects.push(o);p=o}
    syncAdvance(p);save();toast(ex?'Project updated':'Project created');back();
  }
}
const CATS={expense:['Material','Hardware','Labor','Transport','Installation','Finishing','Outsourcing','CNC-Machine','Fuel','Food-Allowance','Miscellaneous','Refund','Other'],income:['Customer Payment','Refund','Other']};
function fillCats(){$('#category').innerHTML=CATS[$('#type').value].map(x=>`<option>${x}</option>`).join('')}
function renderTxEdit(id){
  let t=db.transactions.find(x=>x.id===id);if(!t)return;
  $('#screen').innerHTML=add();bind('add');
  editTxId=id;
  const opt=(sel,val)=>{if(val&&![...sel.options].some(o=>o.value===val||o.textContent===val))sel.add(new Option(val,val));sel.value=val};
  $('#screen h2').textContent='Edit transaction';
  $('#type').value=t.type;fillCats();
  $('#project').value=t.projectId||'';setDateField('date',t.date||today());$('#amount').value=t.amount;
  opt($('#category'),t.category);opt($('#method'),t.method||'Cash');
  $('#desc').value=t.description||'';$('#paid').value=t.paidTo||'';
  if(t.isAdvance){$('#type').disabled=true;$('#project').disabled=true;$('#saveTx').insertAdjacentHTML('beforebegin','<div class="small">This is the project\'s advance payment. Changing the amount here also updates the advance on the project.</div>')}
  $('#saveTx').textContent='Save changes';
  $('#saveTx').insertAdjacentHTML('afterend','<button class="btn secondary" id="cancelTx">Cancel</button>');
  $('#cancelTx').onclick=()=>{editTxId=null;const bk=t.projectId&&db.projects.some(p=>p.id===t.projectId)?t.projectId:'__none';curLedger=bk;$('#screen').innerHTML=ledger(bk);bind('ledger')};
}
function saveTx(){let id=$('#project').value,amount=Number($('#amount').value);if(!id){toast('Select a project');return}if(!(amount>0)){toast('Enter an amount greater than zero');return}
  let p=db.projects.find(p=>p.id===id),type=$('#type').value;
  if(editTxId){let t=db.transactions.find(x=>x.id===editTxId);if(t){Object.assign(t,{date:$('#date').value||today(),projectId:id,projectName:p.name,type,category:$('#category').value,amount,description:$('#desc').value.trim(),paidTo:$('#paid').value.trim(),method:$('#method').value});if(t.isAdvance)p.advance=amount;editTxId=null;curLedger=id;save();toast('Transaction updated');$('#screen').innerHTML=ledger(id);bind('ledger');return}editTxId=null}
  db.transactions.push({id:newId(),date:$('#date').value||today(),projectId:id,projectName:p.name,type,category:$('#category').value,amount,description:$('#desc').value.trim(),paidTo:$('#paid').value.trim(),method:$('#method').value});save();toast('Transaction saved');render('dashboard')}
function renderDaily(){$('#screen').innerHTML=`<div class="content"><h2>Today's Top 3</h2><div class="panel"><label>Revenue task</label><input id="taskRevenue"><label>Business task</label><input id="taskBusiness"><label>Personal development task</label><input id="taskPersonal"><button class="btn" id="saveTop3">Save Top 3</button></div></div>`;$('#saveTop3').onclick=()=>{db.dailyTop3.push({date:today(),revenue:$('#taskRevenue').value,business:$('#taskBusiness').value,personal:$('#taskPersonal').value});save();toast('Top 3 saved');render('plan')}}
function downloadBackup(){downloadBlob(JSON.stringify(db,null,2),'haymani-full-backup-'+today()+'.json','application/json');toast('Backup downloaded')}
function restoreBackup(){let file=$('#restoreFile').files[0];if(!file){toast('Choose a JSON backup first');return}let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result);if(!x||!Array.isArray(x.projects)||!Array.isArray(x.transactions))throw Error('Invalid backup');if(!confirm('Restore backup and replace the current app records? Download a backup first if needed.'))return;db=fixDb(x);save();toast('Backup restored');render('dashboard')}catch(e){toast('That file is not a valid Haymani backup')}};reader.readAsText(file)}
function exportCsv(){exportReportCsv('All recorded transactions',{start:'2000-01-01',end:today()},allMovements(),totalFigures(allMovements()),balanceAt(),balanceAtBefore(today()))}
$('#backupBtn').onclick=downloadBackup;if(navigator.storage&&navigator.storage.persist)navigator.storage.persist();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});render('dashboard');
